def risposta(M, K, C, T0, w):
    A = K - w**2 * M + 1j * w * C
    return np.abs(np.linalg.solve(A, np.asarray(T0, dtype=complex)))

from scipy.integrate import solve_ivp


def transitorio(M, K, C, T, t_fin, n=2000):
    nd = M.shape[0]
    Minv = np.linalg.inv(M)

    def f(t, y):
        th, om = y[:nd], y[nd:]
        return np.concatenate([om, Minv @ (np.asarray(T(t)) - C @ om - K @ th)])

    t = np.linspace(0, t_fin, n)
    sol = solve_ivp(f, (0, t_fin), np.zeros(2 * nd), t_eval=t, rtol=1e-8, atol=1e-10)
    return sol.t, sol.y[:nd]

import matplotlib.pyplot as plt


def curva(M, K, C, T0, f_max, n=600):
    f = np.linspace(0.1, f_max, n)
    A = np.array([risposta(M, K, C, T0, 2 * np.pi * fi) for fi in f])
    fig, ax = plt.subplots(figsize=(6, 3.2))
    for j in range(A.shape[1]):
        ax.semilogy(f, A[:, j], label=f"disco {j}")
    for fn in modi(M, K)[0]:
        if fn <= f_max:
            ax.axvline(fn, ls=":", color="gray")
    ax.set(xlabel="f [Hz]", ylabel="ampiezza [rad]")
    ax.legend()
    return f, A, fig
